using System.IO;
using WpfCodeReview.Models;

namespace WpfCodeReview.Services;

public static class EnvFileWriter
{
    public static void WriteEnvFile(AppSettings settings, string outputPath)
    {
        var lines = new List<string>
        {
            "# Generated by WPF Code Review Tool — do not edit manually",
            "",
            "# ============ DevOps Connection ============",
            $"DevOpsOrgUrl={settings.DevOpsOrgUrl}",
            $"DevOpsAccessToken={settings.DevOpsAccessToken}",
            $"DevOpsProjectName={settings.DevOpsProjectName}",
            $"DevOpsRepositoryId={settings.DevOpsRepositoryId}",
            $"DevOpsPRId={settings.DevOpsPRId}",
            "",
            "# ============ AI Provider ============",
            $"GeminiAPIKey={settings.GeminiAPIKey}",
            $"OpenAIAPIKey={settings.OpenAIAPIKey}",
            $"GrokAPIKey={settings.GrokAPIKey}",
            $"ClaudeAPIKey={settings.ClaudeAPIKey}",
            $"AiProvider={settings.AiProvider}",
            $"ModelName={settings.ModelName}",
            "",
            "# ============ GitHub Copilot ============",
            $"GitHubCopilotServerAddress={settings.GitHubCopilotServerAddress}",
            $"GitHubCopilotToken={settings.GitHubCopilotToken}",
            $"GitHubCopilotTimeout={settings.GitHubCopilotTimeout}",
            "",
            "# ============ Ollama ============",
            $"OllamaBaseUrl={settings.OllamaBaseUrl}",
            "",
            "# ============ AI Generation ============",
            $"SystemInstructionSource={settings.SystemInstructionSource}",
            $"SystemInstruction={settings.SystemInstruction}",
            $"ResponseLanguage={settings.ResponseLanguage}",
            $"MaxOutputTokens={settings.MaxOutputTokens}",
            $"Temperature={settings.Temperature}",
            "",
            "# ============ Diff Filter ============",
            $"FileExtensions={settings.FileExtensions}",
            $"BinaryExtensions={settings.BinaryExtensions}",
            "",
            "# ============ Review Mode ============",
            $"EnableThrottleMode={BoolStr(settings.EnableThrottleMode)}",
            $"ShowReviewContent={BoolStr(settings.ShowReviewContent)}",
            $"EnableIncrementalDiff={BoolStr(settings.EnableIncrementalDiff)}",
            $"WriteReviewResult={BoolStr(settings.WriteReviewResult)}",
            "",
            "# ============ Inline Comment ============",
            $"EnableInlineComments={BoolStr(settings.EnableInlineComments)}",
            $"GroupInlineCommentsByFile={BoolStr(settings.GroupInlineCommentsByFile)}",
            $"InlineStrictMode={BoolStr(settings.InlineStrictMode)}",
        };

        File.WriteAllLines(outputPath, lines, System.Text.Encoding.UTF8);
    }

    private static string BoolStr(bool value) => value ? "true" : "false";
}
